        private readonly Dictionary<string, LegalTransactionRecordData> transactions = new Dictionary<string, LegalTransactionRecordData>(StringComparer.Ordinal);
        private DefinitionRegistry registry; private GovernmentRuntime governments; private OrganizationAuthorityRuntime authority; private OrganizationDecisionRuntime decisions; private DiplomacyRuntime diplomacy; private PropertyRuntime properties; private OrganizationRuntime organizations; private HashSet<string> personIds = new HashSet<string>(StringComparer.Ordinal); private HashSet<string> placeIds = new HashSet<string>(StringComparer.Ordinal); private string worldId = string.Empty; private bool disposed;
