        public IReadOnlyList<LegalInstrumentRecordData> Instruments => instruments.Values.OrderBy(item => item.effectiveWorldTime).ThenBy(item => item.instrumentId, StringComparer.Ordinal).Select(item => item.Clone()).ToArray();
        public IReadOnlyList<LegalProvisionRecordData> Provisions => provisions.Values.OrderBy(item => item.instrumentId, StringComparer.Ordinal).ThenBy(item => item.citation, StringComparer.Ordinal).ThenBy(item => item.provisionId, StringComparer.Ordinal).Select(item => item.Clone()).ToArray();
        public IReadOnlyList<LegalEntitlementRecordData> Entitlements => entitlements.Values.OrderBy(item => item.effectiveWorldTime).ThenBy(item => item.entitlementId, StringComparer.Ordinal).Select(item => item.Clone()).ToArray();
