        public void Configure(DefinitionRegistry definitions, GovernmentRuntime governmentRuntime, OrganizationRuntime organizationRuntime, OrganizationAuthorityRuntime authorityRuntime, OrganizationDecisionRuntime decisionRuntime, DiplomacyRuntime diplomacyRuntime, PropertyRuntime propertyRuntime, string runtimeWorldId, IEnumerable<string> knownPersons, IEnumerable<string> knownPlaces)
        { registry = definitions ?? registry; governments = governmentRuntime; organizations = organizationRuntime; authority = authorityRuntime; decisions = decisionRuntime; diplomacy = diplomacyRuntime; properties = propertyRuntime; worldId = LegalModelUtility.N(runtimeWorldId); personIds = new HashSet<string>(LegalModelUtility.C(knownPersons), StringComparer.Ordinal); placeIds = new HashSet<string>(LegalModelUtility.C(knownPlaces), StringComparer.Ordinal); }

        public bool TryGetInstrument(string id, out LegalInstrumentRecordData value) { if (instruments.TryGetValue(LegalModelUtility.N(id), out LegalInstrumentRecordData found)) { value = found.Clone(); return true; } value = null; return false; }
        public bool TryGetProvision(string id, out LegalProvisionRecordData value) { if (provisions.TryGetValue(LegalModelUtility.N(id), out LegalProvisionRecordData found)) { value = found.Clone(); return true; } value = null; return false; }
        public bool TryGetStatus(string id, out PersonLegalStatusRecordData value) { if (statuses.TryGetValue(LegalModelUtility.N(id), out PersonLegalStatusRecordData found)) { value = found.Clone(); return true; } value = null; return false; }
        public IReadOnlyList<LegalInstrumentRecordData> GetLawsByGovernment(string governmentId) => instruments.Values.Where(item => item.governmentId == LegalModelUtility.N(governmentId)).OrderByDescending(item => item.precedence).ThenBy(item => item.effectiveWorldTime).ThenBy(item => item.instrumentId, StringComparer.Ordinal).Select(item => item.Clone()).ToArray();
        public IReadOnlyList<LegalInstrumentRecordData> GetLawsByJurisdiction(string jurisdictionId) => instruments.Values.Where(item => item.jurisdictionIds.Contains(LegalModelUtility.N(jurisdictionId))).OrderByDescending(item => item.precedence).ThenBy(item => item.instrumentId, StringComparer.Ordinal).Select(item => item.Clone()).ToArray();
        public IReadOnlyList<LegalInstrumentRecordData> GetLawsByPolity(string polityId) { string id = LegalModelUtility.N(polityId); return instruments.Values.Where(item => governments != null && governments.TryGetGovernment(item.governmentId, out GovernmentRecordData government) && government.polityId == id).OrderByDescending(item => item.precedence).ThenBy(item => item.effectiveWorldTime).ThenBy(item => item.instrumentId, StringComparer.Ordinal).Select(item => item.Clone()).ToArray(); }
        public IReadOnlyList<LegalInstrumentRecordData> GetLawsByTerritory(string territoryId) { string id = LegalModelUtility.N(territoryId); return instruments.Values.Where(item => item.jurisdictionIds.Any(jurisdictionId => governments != null && governments.TryGetJurisdiction(jurisdictionId, out JurisdictionRecordData jurisdiction) && jurisdiction.territoryIds.Contains(id))).OrderByDescending(item => item.precedence).ThenBy(item => item.instrumentId, StringComparer.Ordinal).Select(item => item.Clone()).ToArray(); }
        public IReadOnlyList<LegalInstrumentRecordData> GetLawsByCategory(LegalInstrumentCategory category) => instruments.Values.Where(item => Def(item.instrumentDefinitionId, out LegalInstrumentDefinition definition) && definition.Category == category).OrderByDescending(item => item.precedence).ThenBy(item => item.instrumentId, StringComparer.Ordinal).Select(item => item.Clone()).ToArray();
        public IReadOnlyList<LegalInstrumentRecordData> GetLawsByLifecycle(LegalInstrumentLifecycleState state) => instruments.Values.Where(item => item.lifecycleState == state).OrderBy(item => item.effectiveWorldTime).ThenBy(item => item.instrumentId, StringComparer.Ordinal).Select(item => item.Clone()).ToArray();
        public IReadOnlyList<LegalInstrumentRecordData> GetTreatyImplementationLaws(string agreementId) { string id = LegalModelUtility.N(agreementId); return instruments.Values.Where(item => item.sourceAgreementId == id).OrderByDescending(item => item.precedence).ThenBy(item => item.instrumentId, StringComparer.Ordinal).Select(item => item.Clone()).ToArray(); }
        public IReadOnlyList<LegalProvisionRecordData> GetProvisionsForInstrument(string instrumentId) { string id = LegalModelUtility.N(instrumentId); return provisions.Values.Where(item => item.instrumentId == id).OrderBy(item => item.citation, StringComparer.Ordinal).ThenBy(item => item.provisionId, StringComparer.Ordinal).Select(item => item.Clone()).ToArray(); }
        public IReadOnlyList<LegalEntitlementRecordData> GetEntitlementsForPerson(string personId, double worldTime) { string id = LegalModelUtility.N(personId); return entitlements.Values.Where(item => item.personId == id && worldTime >= item.effectiveWorldTime && (item.expirationWorldTime < 0d || worldTime <= item.expirationWorldTime)).OrderBy(item => item.effect).ThenBy(item => item.entitlementId, StringComparer.Ordinal).Select(item => item.Clone()).ToArray(); }
        public IReadOnlyList<PersonLegalStatusRecordData> GetStatusesForPerson(string personId, double worldTime) => statuses.Values.Where(item => item.personId == LegalModelUtility.N(personId) && worldTime >= item.effectiveWorldTime && (item.endedWorldTime < 0d || worldTime <= item.endedWorldTime)).OrderBy(item => item.category).ThenBy(item => item.statusId, StringComparer.Ordinal).Select(item => item.Clone()).ToArray();

        public LegalProjectionResult<LegalInstrumentRecordData> ProjectInstrument(string instrumentId, bool privileged)
        {
            if (!instruments.TryGetValue(LegalModelUtility.N(instrumentId), out LegalInstrumentRecordData source)) return LegalProjectionResult<LegalInstrumentRecordData>.Denied("Legal instrument is missing.");
            if (privileged || source.visibility == PoliticalVisibility.Public)
            {
                return LegalProjectionResult<LegalInstrumentRecordData>.Success(source.Clone(), false, "Full legal instrument projection returned.");
            }

            if (source.visibility == PoliticalVisibility.Hidden) return LegalProjectionResult<LegalInstrumentRecordData>.Denied("Legal instrument is concealed.");
            LegalInstrumentRecordData redacted = source.Clone();
            redacted.title = "Restricted legal instrument";
            redacted.shortTitle = string.Empty;
            redacted.citation = string.Empty;
            redacted.organizationId = string.Empty;
            redacted.officeId = string.Empty;
            redacted.sourceAuthorityGrantId = string.Empty;
            redacted.sourceResolutionId = string.Empty;
            redacted.sourceAgreementId = string.Empty;
            redacted.provisionIds = Array.Empty<string>();
            redacted.amendmentIds = Array.Empty<string>();
            redacted.provenanceId = string.Empty;
            return LegalProjectionResult<LegalInstrumentRecordData>.Success(redacted, true, "Redacted legal instrument projection returned.");
        }

        public LegalProjectionResult<PersonLegalStatusRecordData> ProjectStatus(string statusId, string requesterPersonId, bool privileged)
        {
            if (!statuses.TryGetValue(LegalModelUtility.N(statusId), out PersonLegalStatusRecordData source)) return LegalProjectionResult<PersonLegalStatusRecordData>.Denied("Legal status is missing.");
            bool owner = string.Equals(source.personId, LegalModelUtility.N(requesterPersonId), StringComparison.Ordinal);
            if (privileged || owner || source.visibility == PoliticalVisibility.Public) return LegalProjectionResult<PersonLegalStatusRecordData>.Success(source.Clone(), false, "Full legal status projection returned.");
            if (source.visibility == PoliticalVisibility.Hidden) return LegalProjectionResult<PersonLegalStatusRecordData>.Denied("Legal status is concealed.");
            PersonLegalStatusRecordData redacted = source.Clone();
            redacted.personId = string.Empty;
            redacted.sourceInstrumentId = string.Empty;
            redacted.sourceDecisionId = string.Empty;
            redacted.sourceAuthorityGrantId = string.Empty;
            redacted.recognitionRelationId = string.Empty;
            redacted.residencePlaceId = string.Empty;
            redacted.provenanceId = string.Empty;
            return LegalProjectionResult<PersonLegalStatusRecordData>.Success(redacted, true, "Redacted legal status projection returned.");
        }

        public LegalOperationResult Enact(EnactLegalInstrumentRequest request)
        {
            request ??= new EnactLegalInstrumentRequest(); long before = Revision; if (!Ready(out LegalOperationResult failure)) return failure; string id = LegalModelUtility.N(request.instrumentId); if (Duplicate(request.transactionId, "enact", id, before, out LegalOperationResult duplicate)) return duplicate;
            if (string.IsNullOrEmpty(id) || instruments.ContainsKey(id)) return Fail(LegalOperationCode.InvalidRequest, $"Legal instrument '{id}' is missing an ID or already exists.", before);
            if (!Def(request.instrumentDefinitionId, out LegalInstrumentDefinition definition)) return Fail(LegalOperationCode.MissingDefinition, $"Legal Instrument definition '{request.instrumentDefinitionId}' is missing.", before);
            if (!Def(request.authorityDefinitionId, out LegalAuthorityDefinition authorityDefinition)) return Fail(LegalOperationCode.MissingDefinition, $"Legal Authority definition '{request.authorityDefinitionId}' is missing.", before);
            if (!authorityDefinition.InstrumentCategories.Contains(definition.Category)) return Fail(LegalOperationCode.MissingAuthority, "Legal authority cannot enact this instrument category.", before);
            if (governments == null || !governments.TryGetGovernment(request.governmentId, out GovernmentRecordData government)) return Fail(LegalOperationCode.MissingGovernment, $"Government '{request.governmentId}' is missing.", before);
            if (government.lifecycleState != GovernmentLifecycleState.Active && government.lifecycleState != GovernmentLifecycleState.Provisional && government.lifecycleState != GovernmentLifecycleState.InExile && government.lifecycleState != GovernmentLifecycleState.OccupationAdministration) return Fail(LegalOperationCode.InvalidState, "Enacting government is not legally active.", before);
            if (authorityDefinition.GovernmentLevels.Count > 0 && !authorityDefinition.GovernmentLevels.Contains(government.level)) return Fail(LegalOperationCode.MissingAuthority, "Government level is outside legal authority.", before);
            string[] jurisdictionIds = LegalModelUtility.C(request.jurisdictionIds); if (jurisdictionIds.Length == 0) return Fail(LegalOperationCode.MissingJurisdiction, "At least one jurisdiction is required.", before);
            foreach (string jurisdictionId in jurisdictionIds) { if (!governments.TryGetJurisdiction(jurisdictionId, out JurisdictionRecordData jurisdiction)) return Fail(LegalOperationCode.MissingJurisdiction, $"Jurisdiction '{jurisdictionId}' is missing.", before); if (jurisdiction.governmentId != government.governmentId) return Fail(LegalOperationCode.MissingAuthority, $"Government does not own jurisdiction '{jurisdictionId}'.", before); if (authorityDefinition.JurisdictionCategories.Count > 0 && !authorityDefinition.JurisdictionCategories.Contains(jurisdiction.category)) return Fail(LegalOperationCode.MissingAuthority, "Jurisdiction category is outside legal authority.", before); }
            if (!ValidateGrant(request.sourceAuthorityGrantId, government.primaryGoverningOrganizationId, request.trustedSystemOperation, out string grantFailure)) return Fail(LegalOperationCode.MissingAuthority, grantFailure, before);
            if (!request.trustedSystemOperation && authority.TryGetGrant(request.sourceAuthorityGrantId, out OrganizationAuthoritySnapshot authorityGrant) && authorityDefinition.RequiredPermissionIds.Except(authorityGrant.Data.permissionDefinitionIds, StringComparer.Ordinal).Any()) return Fail(LegalOperationCode.MissingAuthority, "Authority grant lacks a permission required by the legal authority definition.", before);
            if (!ValidateResolution(request.sourceResolutionId)) return Fail(LegalOperationCode.MissingResolution, $"Source resolution '{request.sourceResolutionId}' is missing.", before);
            if (definition.Category == LegalInstrumentCategory.TreatyImplementationAct && (string.IsNullOrWhiteSpace(request.sourceAgreementId) || diplomacy == null || !diplomacy.TryGetAgreement(request.sourceAgreementId, out _))) return Fail(LegalOperationCode.InvalidReference, "Treaty implementation requires an existing diplomatic agreement.", before);
            if (request.effectiveWorldTime < request.enactmentWorldTime) return Fail(LegalOperationCode.InvalidRequest, "Law cannot take effect before enactment.", before);
            if (request.published && request.publicationWorldTime < request.enactmentWorldTime) return Fail(LegalOperationCode.InvalidRequest, "Publication cannot precede enactment.", before);
            bool published = request.published; if (definition.RequiresPublication && !published && request.effectiveWorldTime <= request.enactmentWorldTime) return Fail(LegalOperationCode.InvalidState, "Instrument requires publication before immediate effect.", before);
            if (definition.Category == LegalInstrumentCategory.EmergencyOrder && definition.MaximumEmergencyDuration >= 0d && (request.expirationWorldTime < request.effectiveWorldTime || request.expirationWorldTime - request.effectiveWorldTime > definition.MaximumEmergencyDuration)) return Fail(LegalOperationCode.InvalidRequest, "Emergency duration exceeds the instrument definition.", before);
            LegalProvisionCreateRequest[] requested = request.provisions ?? Array.Empty<LegalProvisionCreateRequest>(); if (requested.Length == 0) return Fail(LegalOperationCode.InvalidRequest, "Legal instrument requires at least one provision.", before);
            HashSet<string> provisionIds = new HashSet<string>(StringComparer.Ordinal); List<LegalProvisionRecordData> created = new List<LegalProvisionRecordData>();
            foreach (LegalProvisionCreateRequest provisionRequest in requested) { if (!BuildProvision(id, definition, provisionRequest, request.effectiveWorldTime, request.visibility, provisionIds, before, out LegalProvisionRecordData provision, out failure)) return failure; created.Add(provision); }
            LegalInstrumentRecordData instrument = new LegalInstrumentRecordData { instrumentId = id, instrumentDefinitionId = definition.Id, authorityDefinitionId = authorityDefinition.Id, title = request.title?.Trim() ?? definition.DisplayName, shortTitle = request.shortTitle?.Trim() ?? string.Empty, citation = request.citation?.Trim() ?? string.Empty, governmentId = government.governmentId, organizationId = LegalModelUtility.N(request.organizationId), officeId = LegalModelUtility.N(request.officeId), sourceAuthorityGrantId = LegalModelUtility.N(request.sourceAuthorityGrantId), sourceResolutionId = LegalModelUtility.N(request.sourceResolutionId), sourceAgreementId = LegalModelUtility.N(request.sourceAgreementId), jurisdictionIds = jurisdictionIds, provisionIds = created.Select(item => item.provisionId).ToArray(), lifecycleState = request.effectiveWorldTime > request.enactmentWorldTime ? LegalInstrumentLifecycleState.Scheduled : LegalInstrumentLifecycleState.Active, published = published, promulgated = request.promulgated, enactmentWorldTime = request.enactmentWorldTime, publicationWorldTime = published ? request.publicationWorldTime : -1d, effectiveWorldTime = request.effectiveWorldTime, expirationWorldTime = request.expirationWorldTime, precedence = definition.Precedence, conflictPolicy = definition.ConflictPolicy, visibility = request.visibility, provenanceId = LegalModelUtility.N(request.provenanceId), revision = 1 };
            if (request.preview) return LegalOperationResult.Success("Legal enactment previewed.", before, before, id, preview: true);
            instruments[id] = instrument; foreach (LegalProvisionRecordData provision in created) provisions[provision.provisionId] = provision; Complete(request.transactionId, "enact", id); Revision++; return Commit(LegalOperationResult.Success("Legal instrument enacted atomically.", before, Revision, id));
        }

        public LegalOperationResult AddProvision(AddLegalProvisionRequest request)
        {
            request ??= new AddLegalProvisionRequest();
            long before = Revision;
            if (!Ready(out LegalOperationResult failure)) return failure;
            string instrumentId = LegalModelUtility.N(request.instrumentId);
            string provisionId = LegalModelUtility.N(request.provision?.provisionId);
            if (Duplicate(request.transactionId, "add-provision", provisionId, before, out LegalOperationResult duplicate)) return duplicate;
            if (!instruments.TryGetValue(instrumentId, out LegalInstrumentRecordData instrument)) return Fail(LegalOperationCode.MissingInstrument, $"Instrument '{instrumentId}' is missing.", before);
            if (!Def(instrument.instrumentDefinitionId, out LegalInstrumentDefinition instrumentDefinition) || !instrumentDefinition.AllowsAmendment) return Fail(LegalOperationCode.InvalidState, "Instrument does not allow new provisions.", before);
            if (!ValidateGrant(request.sourceAuthorityGrantId, instrument.organizationId, request.trustedSystemOperation, out string grantFailure)) return Fail(LegalOperationCode.MissingAuthority, grantFailure, before);
            if (!BuildProvision(instrumentId, instrumentDefinition, request.provision, request.effectiveWorldTime, instrument.visibility, new HashSet<string>(StringComparer.Ordinal), before, out LegalProvisionRecordData provision, out failure)) return failure;
            if (request.preview) return LegalOperationResult.Success("Provision addition previewed.", before, before, provisionId, preview: true);
            provisions[provision.provisionId] = provision;
            instrument.provisionIds = LegalModelUtility.C(instrument.provisionIds.Concat(new[] { provision.provisionId }));
            instrument.amendmentIds = LegalModelUtility.C(instrument.amendmentIds.Concat(new[] { request.amendmentId }));
            instrument.revision++;
            Complete(request.transactionId, "add-provision", provision.provisionId);
            Revision++;
            return Commit(LegalOperationResult.Success("Provision added to the existing legal instrument.", before, Revision, provision.provisionId));
        }

        public LegalOperationResult AmendProvision(AmendLegalProvisionRequest request)
