            request ??= new AmendLegalProvisionRequest(); long before = Revision; if (!Ready(out LegalOperationResult failure)) return failure; string id = LegalModelUtility.N(request.provisionId); if (Duplicate(request.transactionId, "amend-provision", id, before, out LegalOperationResult duplicate)) return duplicate; if (!provisions.TryGetValue(id, out LegalProvisionRecordData current)) return Fail(LegalOperationCode.MissingProvision, $"Provision '{id}' is missing.", before); if (!instruments.TryGetValue(current.instrumentId, out LegalInstrumentRecordData instrument) || !Def(instrument.instrumentDefinitionId, out LegalInstrumentDefinition instrumentDefinition) || !instrumentDefinition.AllowsAmendment) return Fail(LegalOperationCode.InvalidState, "Instrument does not allow amendment.", before); if (!ValidateGrant(request.sourceAuthorityGrantId, instrument.organizationId, request.trustedSystemOperation, out string grantFailure)) return Fail(LegalOperationCode.MissingAuthority, grantFailure, before);
            LegalProvisionVersionData prior = current.versions.OrderByDescending(item => item.version).First().Clone(); if (request.effectiveWorldTime <= prior.effectiveWorldTime) return Fail(LegalOperationCode.InvalidRequest, "Amendment must begin after the existing version.", before); prior.endedWorldTime = request.effectiveWorldTime; LegalProvisionVersionData next = request.version?.Clone() ?? new LegalProvisionVersionData(); next.version = prior.version + 1; next.effectiveWorldTime = request.effectiveWorldTime; next.sourceAmendmentId = LegalModelUtility.N(request.amendmentId); if (next.effect == LegalEffectCategory.Unknown) next.effect = prior.effect; LegalProvisionRecordData changed = current.Clone(); changed.versions = changed.versions.Where(item => item.version != prior.version).Concat(new[] { prior, next }).OrderBy(item => item.version).ToArray(); changed.revision++;
            if (request.preview) return LegalOperationResult.Success("Provision amendment previewed.", before, before, id, preview: true); provisions[id] = changed; instrument.amendmentIds = LegalModelUtility.C(instrument.amendmentIds.Concat(new[] { request.amendmentId })); instrument.revision++; Complete(request.transactionId, "amend-provision", id); Revision++; return Commit(LegalOperationResult.Success("Provision amended with historical version preserved.", before, Revision, id));
        }

