ity.C(changedSuccessor.predecessorInstrumentIds.Concat(new[] { id })); changedSuccessor.revision++; } if (request.preview) return LegalOperationResult.Success("Instrument transition previewed.", before, before, id, preview: true); instruments[id] = changed; if (changedSuccessor != null) instruments[successorId] = changedSuccessor; Complete(request.transactionId, "transition-instrument", id); Revision++; return Commit(LegalOperationResult.Success("Instrument lifecycle transitioned.", before, Revision, id));
