            request ??= new LegalStatusGrantRequest(); long before = Revision; if (!Ready(out LegalOperationResult failure)) return failure; string id = LegalModelUtility.N(request.statusId); if (Duplicate(request.transactionId, "grant-status", id, before, out LegalOperationResult duplicate)) return duplicate; if (string.IsNullOrEmpty(id) || statuses.ContainsKey(id)) return Fail(LegalOperationCode.InvalidRequest, $"Legal status '{id}' is invalid or already exists.", before); if (!Def(request.statusDefinitionId, out LegalStatusDefinition definition)) return Fail(LegalOperationCode.MissingDefinition, $"Legal Status definition '{request.statusDefinitionId}' is missing.", before); if (!ValidatePerson(request.personId)) return Fail(LegalOperationCode.MissingPerson, $"Person '{request.personId}' is missing.", before); if (definition.RequiresPolity && (governments == null || !governments.TryGetPolity(request.polityId, out _))) return Fail(LegalOperationCode.InvalidReference, $"Polity '{request.polityId}' is missing.", before); CitizenshipDefinition citizenship = null; if (definition.Category == LegalStatusCategory.Citizen) { if (!Def(request.citizenshipDefinitionId, out citizenship)) return Fail(LegalOperationCode.MissingDefinition, $"Citizenship definition '{request.citizenshipDefinitionId}' is missing.", before); if (!citizenship.Routes.Contains(request.acquisitionRoute)) return Fail(LegalOperationCode.InvalidRequest, "Citizenship acquisition route is not supported.", before); if (citizenship.RequiresConsent && !request.consentGiven && request.acquisitionRoute != CitizenshipAcquisitionRoute.Birth && request.acquisitionRoute != CitizenshipAcquisitionRoute.Succession) return Fail(LegalOperationCode.InvalidState, "Citizenship acquisition requires explicit consent.", before); }
            if (!string.IsNullOrWhiteSpace(request.recognizingGovernmentId) && (governments == null || !governments.TryGetGovernment(request.recognizingGovernmentId, out _))) return Fail(LegalOperationCode.MissingGovernment, $"Recognizing government '{request.recognizingGovernmentId}' is missing.", before);
            if (!string.IsNullOrWhiteSpace(request.sourceInstrumentId) && !instruments.ContainsKey(request.sourceInstrumentId.Trim())) return Fail(LegalOperationCode.MissingInstrument, $"Source instrument '{request.sourceInstrumentId}' is missing.", before);
            if (!ValidateResolution(request.sourceDecisionId)) return Fail(LegalOperationCode.MissingResolution, $"Source resolution '{request.sourceDecisionId}' is missing.", before);
            if (!string.IsNullOrWhiteSpace(request.residencePlaceId) && placeIds.Count > 0 && !placeIds.Contains(request.residencePlaceId.Trim())) return Fail(LegalOperationCode.InvalidReference, $"Residence place '{request.residencePlaceId}' is missing.", before);
            bool multipleAllowed = definition.AllowsMultiple && (citizenship == null || citizenship.AllowsMultiple); if (!multipleAllowed && statuses.Values.Any(item => item.personId == LegalModelUtility.N(request.personId) && item.category == definition.Category && item.lifecycleState == LegalStatusLifecycleState.Active)) return Fail(LegalOperationCode.Conflict, "Status definition does not allow multiple active records.", before); if (!ValidateGrant(request.sourceAuthorityGrantId, request.organizationId, request.trustedSystemOperation, out string grantFailure)) return Fail(LegalOperationCode.MissingAuthority, grantFailure, before);
            PersonLegalStatusRecordData record = new PersonLegalStatusRecordData { statusId = id, statusDefinitionId = definition.Id, citizenshipDefinitionId = LegalModelUtility.N(request.citizenshipDefinitionId), personId = LegalModelUtility.N(request.personId), polityId = LegalModelUtility.N(request.polityId), recognizingGovernmentId = LegalModelUtility.N(request.recognizingGovernmentId), residencePlaceId = LegalModelUtility.N(request.residencePlaceId), category = definition.Category, acquisitionRoute = request.acquisitionRoute, lifecycleState = LegalStatusLifecycleState.Active, consentGiven = request.consentGiven, sourceInstrumentId = LegalModelUtility.N(request.sourceInstrumentId), sourceDecisionId = LegalModelUtility.N(request.sourceDecisionId), sourceAuthorityGrantId = LegalModelUtility.N(request.sourceAuthorityGrantId), recognitionRelationId = LegalModelUtility.N(request.recognitionRelationId), effectiveWorldTime = request.effectiveWorldTime, visibility = request.visibility, provenanceId = LegalModelUtility.N(request.provenanceId), revision = 1 }; if (request.preview) return LegalOperationResult.Success("Legal status previewed.", before, before, id, preview: true); statuses[id] = record; Complete(request.transactionId, "grant-status", id); Revision++; return Commit(LegalOperationResult.Success("Legal status granted without changing residence or membership.", before, Revision, id));
        }

        public LegalOperationResult TransitionLegalStatus(LegalStatusTransitionRequest request)
