        public LegalApplicabilityResult Evaluate(LegalApplicabilityRequest request)
        {
            request ??= new LegalApplicabilityRequest(); if (disposed) return LegalApplicabilityResult.Create(LegalApplicabilityStatus.InvalidRequest, null, null, "Legal runtime is disposed.");
            var applicable = provisions.Values.Select(provision => new { Provision = provision, Version = provision.VersionAt(request.worldTime), Instrument = instruments.TryGetValue(provision.instrumentId, out LegalInstrumentRecordData instrument) ? instrument : null }).Where(item => item.Version != null && item.Instrument != null && IsActive(item.Instrument, request.worldTime) && item.Provision.lifecycleState == LegalProvisionLifecycleState.Active && MatchesInstrumentJurisdiction(item.Instrument, request) && Matches(item.Version, request)).OrderByDescending(item => item.Instrument.precedence).ThenByDescending(item => Specificity(item.Version)).ThenByDescending(item => item.Instrument.effectiveWorldTime).ThenBy(item => item.Provision.provisionId, StringComparer.Ordinal).ToArray();
            var individual = entitlements.Values.Where(item => item.lifecycleState == LegalEntitlementLifecycleState.Active && request.worldTime >= item.effectiveWorldTime && (item.expirationWorldTime < 0d || request.worldTime <= item.expirationWorldTime) && Match(item.personId, request.personId) && Match(item.organizationId, request.organizationId) && Match(item.actionId, request.actionId) && Match(item.territoryId, request.territoryId) && Match(item.propertyId, request.propertyId)).OrderBy(item => item.entitlementId, StringComparer.Ordinal).ToArray();
            if (applicable.Length == 0 && individual.Length == 0) return LegalApplicabilityResult.Create(LegalApplicabilityStatus.NoApplicableLaw, null, null, "No applicable legal rule.");
            int top = applicable.Length == 0 ? int.MinValue : applicable[0].Instrument.precedence;
            var controlling = applicable.Where(item => item.Instrument.precedence == top).ToArray();
            if (controlling.Any(item => item.Instrument.conflictPolicy == LegalConflictPolicy.SpecificOverridesGeneral))
            {
                int mostSpecific = controlling.Max(item => Specificity(item.Version));
                controlling = controlling.Where(item => Specificity(item.Version) == mostSpecific).ToArray();
            }
            if (controlling.Any(item => item.Instrument.conflictPolicy == LegalConflictPolicy.LaterInstrumentWins))
            {
                double latest = controlling.Max(item => item.Instrument.effectiveWorldTime);
                controlling = controlling.Where(item => item.Instrument.effectiveWorldTime == latest).ToArray();
            }
            LegalEffectCategory[] topEffects = controlling.Select(item => item.Version.effect).Distinct().ToArray();
            bool opposed = topEffects.Contains(LegalEffectCategory.Prohibition) && (topEffects.Contains(LegalEffectCategory.Permission) || topEffects.Contains(LegalEffectCategory.Right));
            if (opposed && controlling.Any(item => item.Instrument.conflictPolicy == LegalConflictPolicy.Unresolved)) return LegalApplicabilityResult.Create(LegalApplicabilityStatus.Conflict, applicable.Select(item => item.Provision), controlling.Select(item => item.Provision.provisionId), "Unresolved legal conflict.");
            LegalEffectCategory[] effects = controlling.Select(item => item.Version.effect).Concat(individual.Select(item => item.effect)).ToArray();
            LegalApplicabilityStatus status = effects.Contains(LegalEffectCategory.Immunity) ? LegalApplicabilityStatus.Immune : effects.Contains(LegalEffectCategory.Exemption) ? LegalApplicabilityStatus.Exempt : effects.Contains(LegalEffectCategory.Prohibition) ? LegalApplicabilityStatus.Prohibited : effects.Contains(LegalEffectCategory.Duty) ? LegalApplicabilityStatus.Required : effects.Any(item => item == LegalEffectCategory.Permission || item == LegalEffectCategory.Right) ? LegalApplicabilityStatus.Permitted : LegalApplicabilityStatus.Applicable;
            return LegalApplicabilityResult.Create(status, applicable.Select(item => item.Provision), null, "Applicable law resolved deterministically by jurisdiction, precedence, specificity, and instrument policy.");
        }

        public LegalActionAuthorizationResult EvaluateAuthorizedAction(OrganizationAuthorizationRequest authorizationRequest, LegalApplicabilityRequest applicabilityRequest)
        {
            OrganizationAuthorizationResult authorization = authority?.EvaluateAuthorization(authorizationRequest ?? new OrganizationAuthorizationRequest());
            return new LegalActionAuthorizationResult(authorization, Evaluate(applicabilityRequest));
        }

        public LegalOperationResult ProcessWorldTime(LegalTimeEvaluationRequest request)
        {
            request ??= new LegalTimeEvaluationRequest(); long before = Revision; if (!Ready(out LegalOperationResult failure)) return failure; string boundary = LegalModelUtility.N(request.boundaryId); if (Duplicate(request.transactionId, "process-time", boundary, before, out LegalOperationResult duplicate)) return duplicate; if (string.IsNullOrEmpty(boundary)) return Fail(LegalOperationCode.InvalidRequest, "Time boundary ID is required.", before); int limit = Math.Max(1, request.maximumOperations); var due = instruments.Values.Where(item => item.lifecycleState == LegalInstrumentLifecycleState.Scheduled && request.worldTime >= item.effectiveWorldTime && (!Def(item.instrumentDefinitionId, out LegalInstrumentDefinition definition) || !definition.RequiresPublication || item.published)).Select(item => new { Kind = 0, Time = item.effectiveWorldTime, Id = item.instrumentId, Instrument = item, Entitlement = (LegalEntitlementRecordData)null, Transition = (LegalTransitionPlanRecordData)null }).Concat(instruments.Values.Where(item => (item.lifecycleState == LegalInstrumentLifecycleState.Active || item.lifecycleState == LegalInstrumentLifecycleState.Suspended) && item.expirationWorldTime >= 0d && request.worldTime > item.expirationWorldTime).Select(item => new { Kind = 1, Time = item.expirationWorldTime, Id = item.instrumentId, Instrument = item, Entitlement = (LegalEntitlementRecordData)null, Transition = (LegalTransitionPlanRecordData)null })).Concat(entitlements.Values.Where(item => item.lifecycleState == LegalEntitlementLifecycleState.Active && item.expirationWorldTime >= 0d && request.worldTime > item.expirationWorldTime).Select(item => new { Kind = 2, Time = item.expirationWorldTime, Id = item.entitlementId, Instrument = (LegalInstrumentRecordData)null, Entitlement = item, Transition = (LegalTransitionPlanRecordData)null })).Concat(transitions.Values.Where(item => !item.executed && request.worldTime >= item.plannedWorldTime).Select(item => new { Kind = 3, Time = item.plannedWorldTime, Id = item.transitionId, Instrument = (LegalInstrumentRecordData)null, Entitlement = (LegalEntitlementRecordData)null, Transition = item })).OrderBy(item => item.Time).ThenBy(item => item.Kind).ThenBy(item => item.Id, StringComparer.Ordinal).ToArray(); var selected = due.Take(limit).ToArray(); if (request.preview) return LegalOperationResult.Success($"Legal time preview: {selected.Length} of {due.Length} due operations selected.", before, before, boundary, preview: true); foreach (var item in selected) { if (item.Kind == 0) item.Instrument.lifecycleState = LegalInstrumentLifecycleState.Active; else if (item.Kind == 1) item.Instrument.lifecycleState = LegalInstrumentLifecycleState.Expired; else if (item.Kind == 2) item.Entitlement.lifecycleState = LegalEntitlementLifecycleState.Expired; else { item.Transition.executed = true; item.Transition.executedWorldTime = request.worldTime; item.Transition.revision++; continue; } if (item.Instrument != null) item.Instrument.revision++; if (item.Entitlement != null) item.Entitlement.revision++; } Complete(request.transactionId, "process-time", boundary); Revision++; return Commit(LegalOperationResult.Success($"Legal time boundary processed {selected.Length} operation(s); {due.Length - selected.Length} remain pending.", before, Revision, boundary));
        }

        public LegalOperationResult PlanTransition(LegalTransitionPlanRequest request)
        {
            request ??= new LegalTransitionPlanRequest();
            long before = Revision;
            if (!Ready(out LegalOperationResult failure)) return failure;
            string id = LegalModelUtility.N(request.transitionId);
            if (Duplicate(request.transactionId, "plan-transition", id, before, out LegalOperationResult duplicate)) return duplicate;
            if (string.IsNullOrEmpty(id) || transitions.ContainsKey(id) || request.kind == LegalTransitionKind.Unknown) return Fail(LegalOperationCode.InvalidRequest, "Legal transition identity or kind is invalid.", before);
            if (!string.IsNullOrWhiteSpace(request.sourceInstrumentId) && !instruments.ContainsKey(request.sourceInstrumentId.Trim())) return Fail(LegalOperationCode.MissingInstrument, "Transition source instrument is missing.", before);
            if (!string.IsNullOrWhiteSpace(request.targetInstrumentId) && !instruments.ContainsKey(request.targetInstrumentId.Trim())) return Fail(LegalOperationCode.MissingInstrument, "Transition target instrument is missing.", before);
            if (!string.IsNullOrWhiteSpace(request.sourcePolityId) && (governments == null || !governments.TryGetPolity(request.sourcePolityId, out _))) return Fail(LegalOperationCode.InvalidReference, "Transition source polity is missing.", before);
            if (!string.IsNullOrWhiteSpace(request.targetPolityId) && (governments == null || !governments.TryGetPolity(request.targetPolityId, out _))) return Fail(LegalOperationCode.InvalidReference, "Transition target polity is missing.", before);
            if (!ValidateResolution(request.sourceDecisionId)) return Fail(LegalOperationCode.MissingResolution, "Transition source decision is missing.", before);
            LegalTransitionPlanRecordData record = new LegalTransitionPlanRecordData { transitionId = id, kind = request.kind, sourceInstrumentId = LegalModelUtility.N(request.sourceInstrumentId), targetInstrumentId = LegalModelUtility.N(request.targetInstrumentId), sourcePolityId = LegalModelUtility.N(request.sourcePolityId), targetPolityId = LegalModelUtility.N(request.targetPolityId), statusIds = LegalModelUtility.C(request.statusIds), sourceDecisionId = LegalModelUtility.N(request.sourceDecisionId), plannedWorldTime = request.plannedWorldTime, diagnostics = request.diagnostics ?? string.Empty, revision = 1 };
            if (record.statusIds.Any(statusId => !statuses.ContainsKey(statusId))) return Fail(LegalOperationCode.MissingStatus, "Transition references a missing legal status.", before);
            if (request.preview) return LegalOperationResult.Success("Legal transition previewed.", before, before, id, preview: true);
            transitions[id] = record;
            Complete(request.transactionId, "plan-transition", id);
            Revision++;
            return Commit(LegalOperationResult.Success("Legal transition plan recorded without mutating government ownership.", before, Revision, id));
        }

        public LegalRuntimeSaveData CreateSaveData() => new LegalRuntimeSaveData { schemaVersion = 1, worldId = worldId, revision = Revision, instruments = Instruments.ToArray(), provisions = Provisions.ToArray(), entitlements = Entitlements.ToArray(), statuses = Statuses.ToArray(), transitions = Transitions.ToArray(), transactions = transactions.Values.OrderBy(item => item.revision).ThenBy(item => item.transactionId, StringComparer.Ordinal).Select(item => item.Clone()).RetainNewestTransactions().ToArray() };
        public LegalOperationResult RestoreFromSaveData(LegalRuntimeSaveData data, DefinitionRegistry definitions, GovernmentRuntime governmentRuntime, OrganizationRuntime organizationRuntime, OrganizationAuthorityRuntime authorityRuntime, OrganizationDecisionRuntime decisionRuntime, DiplomacyRuntime diplomacyRuntime, PropertyRuntime propertyRuntime, string expectedWorldId, IEnumerable<string> knownPersons, IEnumerable<string> knownPlaces)
        { long before = Revision; if (!ValidateSaveData(data, definitions, governmentRuntime, organizationRuntime, authorityRuntime, decisionRuntime, diplomacyRuntime, propertyRuntime, expectedWorldId, knownPersons, knownPlaces, out string failure)) return Fail(LegalOperationCode.ValidationFailed, failure, before); Configure(definitions, governmentRuntime, organizationRuntime, authorityRuntime, decisionRuntime, diplomacyRuntime, propertyRuntime, expectedWorldId, knownPersons, knownPlaces); RestoreInternal(data); return LegalOperationResult.Success("Legal runtime restored.", before, Revision); }
        public static bool ValidateSaveData(LegalRuntimeSaveData data, DefinitionRegistry definitions, GovernmentRuntime governments, OrganizationRuntime organizations, OrganizationAuthorityRuntime authority, OrganizationDecisionRuntime decisions, DiplomacyRuntime diplomacy, PropertyRuntime properties, string expectedWorldId, IEnumerable<string> persons, IEnumerable<string> places, out string failure)
        {
            failure = string.Empty;
            if (data == null) { failure = "Legal save data is missing."; return false; }
            if (data.schemaVersion != 1) { failure = $"Unsupported legal schema {data.schemaVersion}."; return false; }
            if (!string.Equals(LegalModelUtility.N(data.worldId), LegalModelUtility.N(expectedWorldId), StringComparison.Ordinal)) { failure = "Legal save world does not match runtime world."; return false; }

            LegalInstrumentRecordData[] savedInstruments = data.instruments ?? Array.Empty<LegalInstrumentRecordData>();
            LegalProvisionRecordData[] savedProvisions = data.provisions ?? Array.Empty<LegalProvisionRecordData>();
            LegalEntitlementRecordData[] savedEntitlements = data.entitlements ?? Array.Empty<LegalEntitlementRecordData>();
            PersonLegalStatusRecordData[] savedStatuses = data.statuses ?? Array.Empty<PersonLegalStatusRecordData>();
            LegalTransitionPlanRecordData[] savedTransitions = data.transitions ?? Array.Empty<LegalTransitionPlanRecordData>();
            LegalTransactionRecordData[] savedTransactions = data.transactions ?? Array.Empty<LegalTransactionRecordData>();
            if (savedInstruments.Any(item => item == null) || savedProvisions.Any(item => item == null) || savedEntitlements.Any(item => item == null) || savedStatuses.Any(item => item == null) || savedTransitions.Any(item => item == null) || savedTransactions.Any(item => item == null)) { failure = "Legal save contains a null record."; return false; }
            if (!Unique(savedInstruments.Select(item => item.instrumentId), "instrument", out failure)
                || !Unique(savedProvisions.Select(item => item.provisionId), "provision", out failure)
                || !Unique(savedEntitlements.Select(item => item.entitlementId), "entitlement", out failure)
                || !Unique(savedStatuses.Select(item => item.statusId), "status", out failure)
                || !Unique(savedTransitions.Select(item => item.transitionId), "transition", out failure)
                || !Unique(savedTransactions.Select(item => item.transactionId), "transaction", out failure)) return false;

            Dictionary<string, LegalInstrumentRecordData> instrumentById = savedInstruments.ToDictionary(item => item.instrumentId, StringComparer.Ordinal);
            Dictionary<string, LegalProvisionRecordData> provisionById = savedProvisions.ToDictionary(item => item.provisionId, StringComparer.Ordinal);
            HashSet<string> statusIds = new HashSet<string>(savedStatuses.Select(item => item.statusId), StringComparer.Ordinal);
            HashSet<string> personSet = new HashSet<string>(LegalModelUtility.C(persons), StringComparer.Ordinal);
            HashSet<string> placeSet = new HashSet<string>(LegalModelUtility.C(places), StringComparer.Ordinal);

            foreach (LegalInstrumentRecordData item in savedInstruments)
            {
                if (definitions == null || !definitions.TryGet(item.instrumentDefinitionId, out LegalInstrumentDefinition instrumentDefinition) || !definitions.TryGet(item.authorityDefinitionId, out LegalAuthorityDefinition authorityDefinition)) { failure = $"Instrument '{item.instrumentId}' has missing definitions."; return false; }
                if (!authorityDefinition.InstrumentCategories.Contains(instrumentDefinition.Category)) { failure = $"Instrument '{item.instrumentId}' uses an authority that cannot enact its category."; return false; }
                if (item.lifecycleState == LegalInstrumentLifecycleState.Unknown || item.lifecycleState == LegalInstrumentLifecycleState.Invalid) { failure = $"Instrument '{item.instrumentId}' has an invalid lifecycle."; return false; }
                if (item.effectiveWorldTime < item.enactmentWorldTime || item.expirationWorldTime >= 0d && item.expirationWorldTime < item.effectiveWorldTime) { failure = $"Instrument '{item.instrumentId}' has invalid effective dates."; return false; }
                if (item.published && item.publicationWorldTime < item.enactmentWorldTime) { failure = $"Instrument '{item.instrumentId}' has an invalid publication time."; return false; }
                if (instrumentDefinition.RequiresPublication && item.lifecycleState == LegalInstrumentLifecycleState.Active && !item.published && item.visibility != PoliticalVisibility.Hidden && item.visibility != PoliticalVisibility.Secret) { failure = $"Instrument '{item.instrumentId}' is active without required publication."; return false; }
                if (governments == null || !governments.TryGetGovernment(item.governmentId, out GovernmentRecordData government)) { failure = $"Instrument '{item.instrumentId}' has missing government."; return false; }
                if (!string.IsNullOrWhiteSpace(item.organizationId) && (organizations == null || !organizations.TryGetSnapshot(item.organizationId, out _))) { failure = $"Instrument '{item.instrumentId}' has missing organization."; return false; }
                if (!string.IsNullOrWhiteSpace(item.sourceAuthorityGrantId) && (authority == null || !authority.TryGetGrant(item.sourceAuthorityGrantId, out _))) { failure = $"Instrument '{item.instrumentId}' has missing authority grant."; return false; }
                if (!string.IsNullOrWhiteSpace(item.sourceResolutionId) && (decisions == null || !decisions.CreateSaveData().resolutions.Any(resolution => resolution.resolutionId == item.sourceResolutionId))) { failure = $"Instrument '{item.instrumentId}' has missing source resolution."; return false; }
                if (!string.IsNullOrWhiteSpace(item.sourceAgreementId) && (diplomacy == null || !diplomacy.TryGetAgreement(item.sourceAgreementId, out _))) { failure = $"Instrument '{item.instrumentId}' has missing source agreement."; return false; }
                foreach (string jurisdictionId in LegalModelUtility.C(item.jurisdictionIds))
                {
                    if (!governments.TryGetJurisdiction(jurisdictionId, out JurisdictionRecordData jurisdiction)) { failure = $"Instrument '{item.instrumentId}' has missing jurisdiction '{jurisdictionId}'."; return false; }
                    if (jurisdiction.governmentId != government.governmentId) { failure = $"Instrument '{item.instrumentId}' references a jurisdiction owned by another government."; return false; }
                }

                string[] actualProvisionIds = savedProvisions.Where(provision => provision.instrumentId == item.instrumentId).Select(provision => provision.provisionId).OrderBy(id => id, StringComparer.Ordinal).ToArray();
                if (!LegalModelUtility.C(item.provisionIds).OrderBy(id => id, StringComparer.Ordinal).SequenceEqual(actualProvisionIds, StringComparer.Ordinal)) { failure = $"Instrument '{item.instrumentId}' provision index does not match its records."; return false; }
                if (LegalModelUtility.C(item.successorInstrumentIds).Any(id => !instrumentById.ContainsKey(id)) || LegalModelUtility.C(item.predecessorInstrumentIds).Any(id => !instrumentById.ContainsKey(id))) { failure = $"Instrument '{item.instrumentId}' has a missing succession link."; return false; }
                if (LegalModelUtility.C(item.successorInstrumentIds).Any(id => !instrumentById[id].predecessorInstrumentIds.Contains(item.instrumentId)) || LegalModelUtility.C(item.predecessorInstrumentIds).Any(id => !instrumentById[id].successorInstrumentIds.Contains(item.instrumentId))) { failure = $"Instrument '{item.instrumentId}' has a non-reciprocal succession link."; return false; }
            }

            foreach (LegalProvisionRecordData item in savedProvisions)
            {
                if (!instrumentById.TryGetValue(item.instrumentId, out LegalInstrumentRecordData instrument) || definitions == null || !definitions.TryGet(item.provisionDefinitionId, out LegalProvisionDefinition provisionDefinition)) { failure = $"Provision '{item.provisionId}' has invalid instrument or definition."; return false; }
                if (!definitions.TryGet(instrument.instrumentDefinitionId, out LegalInstrumentDefinition instrumentDefinition) || provisionDefinition.SupportedInstruments.Count > 0 && !provisionDefinition.SupportedInstruments.Contains(instrumentDefinition.Category)) { failure = $"Provision '{item.provisionId}' does not support its instrument category."; return false; }
                if (item.lifecycleState == LegalProvisionLifecycleState.Unknown || item.versions == null || item.versions.Length == 0 || item.versions.Any(version => version == null)) { failure = $"Provision '{item.provisionId}' has no valid version history."; return false; }
                LegalProvisionVersionData[] versions = item.versions.OrderBy(version => version.version).ToArray();
                if (versions.Select(version => version.version).Distinct().Count() != versions.Length || versions[0].version != 1 || versions.Where((version, index) => version.version != index + 1).Any()) { failure = $"Provision '{item.provisionId}' has an invalid version sequence."; return false; }
                for (int i = 0; i < versions.Length; i++)
                {
                    LegalProvisionVersionData version = versions[i];
                    if (version.effect == LegalEffectCategory.Unknown || version.endedWorldTime >= 0d && version.endedWorldTime < version.effectiveWorldTime) { failure = $"Provision '{item.provisionId}' version {version.version} is invalid."; return false; }
                    if (i > 0 && versions[i - 1].effectiveWorldTime >= version.effectiveWorldTime) { failure = $"Provision '{item.provisionId}' versions are not chronologically ordered."; return false; }
                    if (i > 0 && (versions[i - 1].endedWorldTime < 0d || versions[i - 1].endedWorldTime > version.effectiveWorldTime)) { failure = $"Provision '{item.provisionId}' has overlapping active versions."; return false; }
                    if (LegalModelUtility.C(version.exceptionProvisionIds).Any(id => id == item.provisionId || !provisionById.ContainsKey(id))) { failure = $"Provision '{item.provisionId}' has an invalid exception reference."; return false; }
                    if (LegalModelUtility.C(version.organizationIds).Any(id => organizations == null || !organizations.TryGetSnapshot(id, out _))) { failure = $"Provision '{item.provisionId}' has a missing organization target."; return false; }
                    if (LegalModelUtility.C(version.territoryIds).Any(id => governments == null || !governments.TryGetTerritory(id, out _))) { failure = $"Provision '{item.provisionId}' has a missing territory target."; return false; }
                    if (placeSet.Count > 0 && LegalModelUtility.C(version.placeIds).Any(id => !placeSet.Contains(id))) { failure = $"Provision '{item.provisionId}' has a missing place target."; return false; }
                    if (LegalModelUtility.C(version.propertyIds).Any(id => properties == null || !properties.TryGetProperty(id, out _))) { failure = $"Provision '{item.provisionId}' has a missing property target."; return false; }
                }
            }

            foreach (LegalEntitlementRecordData item in savedEntitlements)
            {
                if (item.effect == LegalEffectCategory.Unknown || item.lifecycleState == LegalEntitlementLifecycleState.Unknown) { failure = $"Entitlement '{item.entitlementId}' has invalid state."; return false; }
                if (!string.IsNullOrEmpty(item.provisionId) && !provisionById.ContainsKey(item.provisionId)) { failure = $"Entitlement '{item.entitlementId}' has missing provision."; return false; }
                if (string.IsNullOrWhiteSpace(item.personId) && string.IsNullOrWhiteSpace(item.organizationId)) { failure = $"Entitlement '{item.entitlementId}' has no target."; return false; }
                if (!string.IsNullOrWhiteSpace(item.personId) && personSet.Count > 0 && !personSet.Contains(item.personId)) { failure = $"Entitlement '{item.entitlementId}' has missing Person."; return false; }
                if (!string.IsNullOrWhiteSpace(item.organizationId) && (organizations == null || !organizations.TryGetSnapshot(item.organizationId, out _))) { failure = $"Entitlement '{item.entitlementId}' has missing organization."; return false; }
                if (!string.IsNullOrWhiteSpace(item.territoryId) && (governments == null || !governments.TryGetTerritory(item.territoryId, out _))) { failure = $"Entitlement '{item.entitlementId}' has missing territory."; return false; }
                if (!string.IsNullOrWhiteSpace(item.propertyId) && (properties == null || !properties.TryGetProperty(item.propertyId, out _))) { failure = $"Entitlement '{item.entitlementId}' has missing property."; return false; }
                if (item.expirationWorldTime >= 0d && item.expirationWorldTime < item.effectiveWorldTime) { failure = $"Entitlement '{item.entitlementId}' has invalid dates."; return false; }
            }

            foreach (PersonLegalStatusRecordData item in savedStatuses)
            {
                if (personSet.Count > 0 && !personSet.Contains(item.personId)) { failure = $"Status '{item.statusId}' has missing Person."; return false; }
                if (definitions == null || !definitions.TryGet(item.statusDefinitionId, out LegalStatusDefinition statusDefinition) || statusDefinition.Category != item.category) { failure = $"Status '{item.statusId}' has missing or mismatched definition."; return false; }
                if (item.lifecycleState == LegalStatusLifecycleState.Unknown || item.endedWorldTime >= 0d && item.endedWorldTime < item.effectiveWorldTime) { failure = $"Status '{item.statusId}' has invalid lifecycle or dates."; return false; }
                if (statusDefinition.RequiresPolity && (governments == null || !governments.TryGetPolity(item.polityId, out _))) { failure = $"Status '{item.statusId}' has missing polity."; return false; }
                if (!string.IsNullOrWhiteSpace(item.recognizingGovernmentId) && (governments == null || !governments.TryGetGovernment(item.recognizingGovernmentId, out _))) { failure = $"Status '{item.statusId}' has missing recognizing government."; return false; }
                if (!string.IsNullOrWhiteSpace(item.sourceInstrumentId) && !instrumentById.ContainsKey(item.sourceInstrumentId)) { failure = $"Status '{item.statusId}' has missing source instrument."; return false; }
                if (!string.IsNullOrWhiteSpace(item.sourceDecisionId) && (decisions == null || !decisions.CreateSaveData().resolutions.Any(resolution => resolution.resolutionId == item.sourceDecisionId))) { failure = $"Status '{item.statusId}' has missing source decision."; return false; }
                if (!string.IsNullOrWhiteSpace(item.sourceAuthorityGrantId) && (authority == null || !authority.TryGetGrant(item.sourceAuthorityGrantId, out _))) { failure = $"Status '{item.statusId}' has missing authority grant."; return false; }
                if (!string.IsNullOrWhiteSpace(item.residencePlaceId) && placeSet.Count > 0 && !placeSet.Contains(item.residencePlaceId)) { failure = $"Status '{item.statusId}' has missing residence place."; return false; }
                if (item.category == LegalStatusCategory.Citizen && (string.IsNullOrWhiteSpace(item.citizenshipDefinitionId) || !definitions.TryGet(item.citizenshipDefinitionId, out CitizenshipDefinition citizenship) || !citizenship.Routes.Contains(item.acquisitionRoute))) { failure = $"Status '{item.statusId}' has invalid citizenship provenance."; return false; }
            }

            foreach (IGrouping<string, PersonLegalStatusRecordData> group in savedStatuses.Where(item => item.lifecycleState == LegalStatusLifecycleState.Active).GroupBy(item => $"{item.personId}|{item.statusDefinitionId}", StringComparer.Ordinal))
            {
                PersonLegalStatusRecordData first = group.First();
                definitions.TryGet(first.statusDefinitionId, out LegalStatusDefinition statusDefinition);
                bool allowsMultiple = statusDefinition?.AllowsMultiple == true;
                if (first.category == LegalStatusCategory.Citizen && definitions.TryGet(first.citizenshipDefinitionId, out CitizenshipDefinition citizenship)) allowsMultiple &= citizenship.AllowsMultiple;
                if (!allowsMultiple && group.Skip(1).Any()) { failure = $"Person '{first.personId}' has duplicate active status '{first.statusDefinitionId}'."; return false; }
            }

            foreach (LegalTransitionPlanRecordData item in savedTransitions)
            {
                if (item.kind == LegalTransitionKind.Unknown || !string.IsNullOrWhiteSpace(item.sourceInstrumentId) && !instrumentById.ContainsKey(item.sourceInstrumentId) || !string.IsNullOrWhiteSpace(item.targetInstrumentId) && !instrumentById.ContainsKey(item.targetInstrumentId) || LegalModelUtility.C(item.statusIds).Any(id => !statusIds.Contains(id))) { failure = $"Transition '{item.transitionId}' has invalid references."; return false; }
                if (!string.IsNullOrWhiteSpace(item.sourcePolityId) && (governments == null || !governments.TryGetPolity(item.sourcePolityId, out _)) || !string.IsNullOrWhiteSpace(item.targetPolityId) && (governments == null || !governments.TryGetPolity(item.targetPolityId, out _))) { failure = $"Transition '{item.transitionId}' has missing polity references."; return false; }
                if (!string.IsNullOrWhiteSpace(item.sourceDecisionId) && (decisions == null || !decisions.CreateSaveData().resolutions.Any(resolution => resolution.resolutionId == item.sourceDecisionId))) { failure = $"Transition '{item.transitionId}' has missing source decision."; return false; }
                if (item.executed && item.executedWorldTime < item.plannedWorldTime) { failure = $"Transition '{item.transitionId}' executed before its planned time."; return false; }
            }

            if (savedTransactions.Any(item => string.IsNullOrWhiteSpace(item.operation) || string.IsNullOrWhiteSpace(item.subjectId))) { failure = "Legal save contains an invalid transaction identity."; return false; }
            return true;
        }
        public void Reset() { instruments.Clear(); provisions.Clear(); entitlements.Clear(); statuses.Clear(); transitions.Clear(); transactions.Clear(); Revision = 0; }
        public void Dispose() { Reset(); OperationCommitted = null; StateChanged = null; disposed = true; }

        private bool BuildProvision(string instrumentId, LegalInstrumentDefinition instrumentDefinition, LegalProvisionCreateRequest request, double effectiveTime, PoliticalVisibility visibility, HashSet<string> ids, long before, out LegalProvisionRecordData record, out LegalOperationResult failure)
        { request ??= new LegalProvisionCreateRequest(); string id = LegalModelUtility.N(request.provisionId); record = null; if (string.IsNullOrEmpty(id) || provisions.ContainsKey(id) || !ids.Add(id)) { failure = Fail(LegalOperationCode.InvalidRequest, $"Provision ID '{id}' is invalid or duplicated.", before); return false; } if (!Def(request.provisionDefinitionId, out LegalProvisionDefinition definition)) { failure = Fail(LegalOperationCode.MissingDefinition, $"Provision definition '{request.provisionDefinitionId}' is missing.", before); return false; } if (definition.SupportedInstruments.Count > 0 && !definition.SupportedInstruments.Contains(instrumentDefinition.Category)) { failure = Fail(LegalOperationCode.InvalidRequest, "Provision definition does not support the instrument category.", before); return false; } LegalProvisionVersionData version = request.version?.Clone() ?? new LegalProvisionVersionData(); version.version = 1; version.effect = definition.EffectCategory; version.effectiveWorldTime = Math.Max(effectiveTime, version.effectiveWorldTime); record = new LegalProvisionRecordData { provisionId = id, instrumentId = instrumentId, provisionDefinitionId = definition.Id, citation = request.citation?.Trim() ?? string.Empty, lifecycleState = version.effectiveWorldTime > effectiveTime ? LegalProvisionLifecycleState.Scheduled : LegalProvisionLifecycleState.Active, versions = new[] { version }, visibility = visibility, revision = 1 }; failure = null; return true; }
        private static bool IsActive(LegalInstrumentRecordData item, double time)
        {
            bool lifecycleApplicable = item.lifecycleState == LegalInstrumentLifecycleState.Active
                || item.lifecycleState == LegalInstrumentLifecycleState.Scheduled && time >= item.effectiveWorldTime;
            bool publicationSatisfied = item.published || item.visibility == PoliticalVisibility.Secret || item.visibility == PoliticalVisibility.Hidden;
            return lifecycleApplicable
                && publicationSatisfied
                && time >= item.effectiveWorldTime
                && (item.expirationWorldTime < 0d || time <= item.expirationWorldTime);
        }
        private static bool Matches(LegalProvisionVersionData item, LegalApplicabilityRequest request) => MatchAny(item.personIds, request.personId) && MatchAny(item.organizationIds, request.organizationId) && MatchAny(item.territoryIds, request.territoryId) && MatchAny(item.placeIds, request.placeId) && MatchAny(item.propertyIds, request.propertyId) && MatchAny(item.officeIds, request.officeId) && MatchAny(item.professionIds, request.professionId) && MatchAny(item.legalStatusDefinitionIds, request.legalStatusDefinitionIds) && Match(item.actionId, request.actionId) && Match(item.subjectMatterId, request.subjectMatterId) && (item.conditions ?? Array.Empty<LegalConditionData>()).All(condition => EvaluateCondition(condition, request));

        private bool MatchesInstrumentJurisdiction(LegalInstrumentRecordData instrument, LegalApplicabilityRequest request)
        {
            if (!string.IsNullOrWhiteSpace(request.governmentId) && !string.Equals(instrument.governmentId, LegalModelUtility.N(request.governmentId), StringComparison.Ordinal)) return false;
            string[] explicitJurisdictions = LegalModelUtility.C((request.jurisdictionIds ?? Array.Empty<string>()).Concat(new[] { request.jurisdictionId }));
            if (explicitJurisdictions.Length > 0 && !instrument.jurisdictionIds.Any(explicitJurisdictions.Contains)) return false;
            foreach (string jurisdictionId in LegalModelUtility.C(instrument.jurisdictionIds))
            {
                if (governments == null || !governments.TryGetJurisdiction(jurisdictionId, out JurisdictionRecordData jurisdiction)) continue;
                if (jurisdiction.lifecycleState != JurisdictionLifecycleState.Active && jurisdiction.lifecycleState != JurisdictionLifecycleState.Delegated) continue;
                if (request.worldTime < jurisdiction.effectiveWorldTime || jurisdiction.expirationWorldTime >= 0d && request.worldTime > jurisdiction.expirationWorldTime) continue;
                if ((jurisdiction.scopeDimensions & JurisdictionScopeDimension.Territory) != 0 && !MatchAny(jurisdiction.territoryIds, request.territoryId)) continue;
                if ((jurisdiction.scopeDimensions & JurisdictionScopeDimension.Place) != 0 && !MatchAny(jurisdiction.placeIds, request.placeId)) continue;
                if ((jurisdiction.scopeDimensions & JurisdictionScopeDimension.Person) != 0 && !MatchAny(jurisdiction.personIds, request.personId)) continue;
                if ((jurisdiction.scopeDimensions & JurisdictionScopeDimension.Organization) != 0 && !MatchAny(jurisdiction.organizationIds, request.organizationId)) continue;
                if ((jurisdiction.scopeDimensions & JurisdictionScopeDimension.Property) != 0 && !MatchAny(jurisdiction.propertyIds, request.propertyId)) continue;
                if ((jurisdiction.scopeDimensions & JurisdictionScopeDimension.Office) != 0 && !MatchAny(jurisdiction.officeIds, request.officeId)) continue;
                if ((jurisdiction.scopeDimensions & JurisdictionScopeDimension.Status) != 0 && !MatchAny(jurisdiction.statusIds, request.legalStatusDefinitionIds)) continue;
                return true;
            }
            return false;
        }
        private static bool EvaluateCondition(LegalConditionData condition, LegalApplicabilityRequest request) { string actual = condition.kind switch { LegalConditionKind.Person => request.personId, LegalConditionKind.Organization => request.organizationId, LegalConditionKind.Territory => request.territoryId, LegalConditionKind.Place => request.placeId, LegalConditionKind.Property => request.propertyId, LegalConditionKind.Office => request.officeId, LegalConditionKind.Profession => request.professionId, LegalConditionKind.Activity => request.actionId, LegalConditionKind.LegalStatus => request.legalStatusDefinitionIds?.FirstOrDefault(value => value == condition.value), _ => string.Empty }; bool match = string.Equals(LegalModelUtility.N(actual), LegalModelUtility.N(condition.value), StringComparison.Ordinal); return condition.negate ? !match : match; }
        private static int Specificity(LegalProvisionVersionData item) => new[] { item.personIds, item.organizationIds, item.territoryIds, item.placeIds, item.propertyIds, item.officeIds, item.professionIds, item.legalStatusDefinitionIds }.Count(values => values != null && values.Length > 0) + (string.IsNullOrEmpty(item.actionId) ? 0 : 1) + (string.IsNullOrEmpty(item.subjectMatterId) ? 0 : 1);
        private static bool MatchAny(IEnumerable<string> expected, string actual) { string[] values = LegalModelUtility.C(expected); return values.Length == 0 || values.Contains(LegalModelUtility.N(actual)); }
        private static bool MatchAny(IEnumerable<string> expected, IEnumerable<string> actual) { string[] values = LegalModelUtility.C(expected); return values.Length == 0 || values.Intersect(LegalModelUtility.C(actual), StringComparer.Ordinal).Any(); }
        private static bool Match(string expected, string actual) => string.IsNullOrWhiteSpace(expected) || string.Equals(LegalModelUtility.N(expected), LegalModelUtility.N(actual), StringComparison.Ordinal);
        private bool ValidatePerson(string personId) => !string.IsNullOrWhiteSpace(personId) && (personIds.Count == 0 || personIds.Contains(personId.Trim()));
        private bool ValidateGrant(string grantId, string organizationId, bool trustedSystemOperation, out string failure) { grantId = LegalModelUtility.N(grantId); if (string.IsNullOrEmpty(grantId)) { failure = trustedSystemOperation ? string.Empty : "An explicit institutional authority grant is required."; return trustedSystemOperation; } if (authority == null || !authority.TryGetGrant(grantId, out OrganizationAuthoritySnapshot grant)) { failure = $"Authority grant '{grantId}' is missing."; return false; } if (grant.LifecycleState != OrganizationAuthorityGrantLifecycleState.Active) { failure = $"Authority grant '{grantId}' is not active."; return false; } if (!string.IsNullOrWhiteSpace(organizationId) && grant.OrganizationId != LegalModelUtility.N(organizationId)) { failure = "Authority grant belongs to another organization."; return false; } failure = string.Empty; return true; }
        private bool ValidateResolution(string resolutionId) { resolutionId = LegalModelUtility.N(resolutionId); return string.IsNullOrEmpty(resolutionId) || decisions != null && decisions.CreateSaveData().resolutions.Any(item => item.resolutionId == resolutionId); }
        private bool Ready(out LegalOperationResult failure) { if (disposed) { failure = Fail(LegalOperationCode.Disposed, "Legal runtime is disposed.", Revision); return false; } if (registry == null || governments == null) { failure = Fail(LegalOperationCode.InvalidState, "Legal runtime dependencies are not ready.", Revision); return false; } failure = null; return true; }
        private bool Def<T>(string id, out T definition) where T : class, IGameDefinition { definition = null; return registry != null && registry.TryGet(LegalModelUtility.N(id), out definition); }
        private bool Duplicate(string tx, string operation, string subject, long before, out LegalOperationResult result) { tx = LegalModelUtility.N(tx); result = null; if (string.IsNullOrEmpty(tx) || !transactions.TryGetValue(tx, out LegalTransactionRecordData existing)) return false; result = existing.operation == operation && existing.subjectId == subject ? LegalOperationResult.Success("Duplicate legal transaction ignored.", before, before, subject, duplicate: true) : Fail(LegalOperationCode.InvalidRequest, $"Transaction '{tx}' has different identity.", before); return true; }
        private void Complete(string tx, string operation, string subject) { tx = LegalModelUtility.N(tx); if (!string.IsNullOrEmpty(tx)) transactions[tx] = new LegalTransactionRecordData { transactionId = tx, operation = operation, subjectId = subject, revision = Revision + 1 }; }
        private LegalOperationResult Commit(LegalOperationResult result) { Action<LegalOperationResult> handlers = OperationCommitted; if (handlers != null) foreach (Action<LegalOperationResult> handler in handlers.GetInvocationList()) try { handler(result); } catch (Exception exception) { Debug.LogException(exception); } LegalTransactionRecordData transaction = transactions.Values.Where(item => item.revision == Revision && item.subjectId == result.SubjectId).OrderBy(item => item.transactionId, StringComparer.Ordinal).FirstOrDefault(); LegalMutationEvent change = new LegalMutationEvent(transaction?.operation ?? string.Empty, result.SubjectId, Revision, result); Action<LegalMutationEvent> changeHandlers = StateChanged; if (changeHandlers != null) foreach (Action<LegalMutationEvent> handler in changeHandlers.GetInvocationList()) try { handler(change); } catch (Exception exception) { Debug.LogException(exception); } return result; }
        private LegalOperationResult Fail(LegalOperationCode code, string message, long revision) => LegalOperationResult.Failure(code, message, revision);
        private static bool Unique(IEnumerable<string> values, string label, out string failure) { string[] ids = (values ?? Array.Empty<string>()).Select(LegalModelUtility.N).ToArray(); if (ids.Any(string.IsNullOrEmpty) || ids.Distinct(StringComparer.Ordinal).Count() != ids.Length) { failure = $"Legal save contains invalid or duplicate {label} IDs."; return false; } failure = string.Empty; return true; }
        private void RestoreInternal(LegalRuntimeSaveData source) { Reset(); LegalRuntimeSaveData data = source.Clone(); worldId = data.worldId; Revision = data.revision; foreach (var item in data.instruments) instruments[item.instrumentId] = item; foreach (var item in data.provisions) provisions[item.provisionId] = item; foreach (var item in data.entitlements) entitlements[item.entitlementId] = item; foreach (var item in data.statuses) statuses[item.statusId] = item; foreach (var item in data.transitions) transitions[item.transitionId] = item; foreach (var item in data.transactions) transactions[item.transactionId] = item; }
    }

    public sealed class LegalProvisionCreateRequest { public string provisionId; public string provisionDefinitionId; public string citation; public LegalProvisionVersionData version; }
    public sealed class EnactLegalInstrumentRequest { public string transactionId; public string instrumentId; public string instrumentDefinitionId; public string authorityDefinitionId; public string title; public string shortTitle; public string citation; public string governmentId; public string organizationId; public string officeId; public string sourceAuthorityGrantId; public string sourceResolutionId; public string sourceAgreementId; public string[] jurisdictionIds = Array.Empty<string>(); public LegalProvisionCreateRequest[] provisions = Array.Empty<LegalProvisionCreateRequest>(); public double enactmentWorldTime; public double publicationWorldTime; public double effectiveWorldTime; public double expirationWorldTime = -1d; public bool published = true; public bool promulgated = true; public PoliticalVisibility visibility; public string provenanceId; public bool trustedSystemOperation; public bool preview; }
    public sealed class AddLegalProvisionRequest { public string transactionId; public string amendmentId; public string instrumentId; public string sourceAuthorityGrantId; public double effectiveWorldTime; public LegalProvisionCreateRequest provision; public bool trustedSystemOperation; public bool preview; }
    public sealed class AmendLegalProvisionRequest { public string transactionId; public string amendmentId; public string provisionId; public string sourceAuthorityGrantId; public double effectiveWorldTime; public LegalProvisionVersionData version; public bool trustedSystemOperation; public bool preview; }
    public sealed class LegalInstrumentTransitionRequest { public string transactionId; public string instrumentId; public LegalInstrumentLifecycleState targetState; public string sourceAuthorityGrantId; public string successorInstrumentId; public double worldTime; public bool trustedSystemOperation; public bool preview; }
    public sealed class PublishLegalInstrumentRequest { public string transactionId; public string instrumentId; public string sourceAuthorityGrantId; public double worldTime; public bool promulgated = true; public bool trustedSystemOperation; public bool preview; }
    public sealed class LegalProvisionTransitionRequest { public string transactionId; public string provisionId; public LegalProvisionLifecycleState targetState; public string sourceAuthorityGrantId; public double worldTime; public bool trustedSystemOperation; public bool preview; }
    public sealed class LegalEntitlementRequest { public string transactionId; public string entitlementId; public LegalEffectCategory effect; public string provisionId; public string personId; public string organizationId; public string actionId; public string territoryId; public string propertyId; public string sourceAuthorityGrantId; public double effectiveWorldTime; public double expirationWorldTime = -1d; public PoliticalVisibility visibility = PoliticalVisibility.Restricted; public string provenanceId; public bool trustedSystemOperation; public bool preview; }
    public sealed class LegalStatusGrantRequest { public string transactionId; public string statusId; public string statusDefinitionId; public string citizenshipDefinitionId; public string personId; public string polityId; public string recognizingGovernmentId; public string residencePlaceId; public string organizationId; public CitizenshipAcquisitionRoute acquisitionRoute; public bool consentGiven; public string sourceInstrumentId; public string sourceDecisionId; public string sourceAuthorityGrantId; public string recognitionRelationId; public double effectiveWorldTime; public PoliticalVisibility visibility = PoliticalVisibility.Restricted; public string provenanceId; public bool trustedSystemOperation; public bool preview; }
    public sealed class LegalStatusTransitionRequest { public string transactionId; public string statusId; public LegalStatusLifecycleState targetState; public string organizationId; public string sourceAuthorityGrantId; public string sourceDecisionId; public bool personConsent; public double worldTime; public bool trustedSystemOperation; public bool preview; }
    public sealed class LegalEntitlementTransitionRequest { public string transactionId; public string entitlementId; public LegalEntitlementLifecycleState targetState; public string sourceAuthorityGrantId; public double worldTime = -1d; public bool trustedSystemOperation; public bool preview; }
    public sealed class LegalTimeEvaluationRequest { public string transactionId; public string boundaryId; public double worldTime; public int maximumOperations = 128; public bool preview; }
    public sealed class LegalTransitionPlanRequest { public string transactionId; public string transitionId; public LegalTransitionKind kind; public string sourceInstrumentId; public string targetInstrumentId; public string sourcePolityId; public string targetPolityId; public string[] statusIds = Array.Empty<string>(); public string sourceDecisionId; public double plannedWorldTime; public string diagnostics; public bool preview; }
}
